action.command:
docker exec startuphafen-devcontainer-maildev-1 node -e '
const net=require("net");
const s=net.connect(1025,"127.0.0.1");
s.on("data",d=>process.stdout.write("<<< "+d.toString()));
let sent=0;
const cmds=["EHLO validator","MAIL FROM:<a@b.de>","RCPT TO:<c@d.de>","DATA","Subject: x",".","QUIT"];
s.on("data",()=>{
  if(sent<cmds.length){ s.write(cmds[sent]+"\r\n"); sent++; }
});
s.on("end",()=>process.exit(0));
setTimeout(()=>{s.end();},4000);
' 2>&1 | head -40

